                </ul>
              </div>
            ))}
          </nav>
        </div>
        <div className='mt-14 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between'>
          <div className='flex flex-col gap-3 sm:flex-row sm:items-center sm:gap-6'>
            <p className='text-muted-foreground text-xs'>{BRAND.copyright}</p>
            <ul className='flex flex-wrap gap-x-5 gap-y-2'>
              {LEGAL_LINKS.map((link) => (
                <li key={link.label}>
                  <a
                    href={link.href}
                    className='text-muted-foreground hover:text-foreground focus-visible:ring-ring/25 rounded-sm text-xs transition-colors outline-none focus-visible:ring-[3px]'
                  >
                    {link.label}
                  </a>
                </li>
              ))}
            </ul>
          </div>
          <div className='-ms-2.5 sm:ms-0 sm:-me-2.5'>
            <BackToTop />
          </div>
        </div>
        <p
          aria-hidden='true'
          className='text-foreground/[0.07] pointer-events-none mt-6 -mb-[0.2em] text-center text-[length:20cqw] leading-none font-semibold whitespace-nowrap select-none'
        >
          {BRAND.wordmark}
        </p>
      </div>
    </footer>
  );
}

'use client';

import { useReducedMotion } from 'motion/react';

import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

const TRAVEL = '-rotate-90 transition-[translate] ease-(--ease-out-strong)';

const LEAVING_ARROW =
  'duration-200 group-hover/button:-translate-y-full group-hover/button:duration-150';

const ARRIVING_ARROW =
  'absolute inset-0 translate-y-full duration-150 group-hover/button:translate-y-0 group-hover/button:duration-200';

function scrollBehaviorOf(shouldReduceMotion: boolean | null): ScrollBehavior {
  if (shouldReduceMotion) {
    return 'auto';
  }
  return 'smooth';
}

export function BackToTop() {
  const shouldReduceMotion = useReducedMotion();

  function scrollToTop() {
    const behavior = scrollBehaviorOf(shouldReduceMotion);
    window.scrollTo({ top: 0, behavior });
  }

  return (
    <Button
      variant='ghost'
      size='sm'
      className='text-muted-foreground'
      onClick={scrollToTop}
    >
      Back to top
      <span
        aria-hidden='true'
        className='relative flex size-3.5 overflow-hidden'
      >
        <ArrowRightIcon className={cn(TRAVEL, LEAVING_ARROW, 'size-3.5')} />
        <ArrowRightIcon className={cn(TRAVEL, ARRIVING_ARROW, 'size-3.5')} />
      </span>
    </Button>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

export function FernwickMark({ className }: { className?: string }) {
  return (
    <svg
      viewBox='0 0 24 24'
      aria-hidden='true'
      className={cn('size-6 shrink-0', className)}
    >
      <rect width='24' height='24' rx='7' className='fill-primary' />
      <path
        d='M8.5 6h7A2.5 2.5 0 0 1 18 8.5v5a2.5 2.5 0 0 1-2.5 2.5H11l-3 2.5V16a2 2 0 0 1-2-2V8.5A2.5 2.5 0 0 1 8.5 6Z'
        className='fill-white'
      />
      <path
        d='M9.5 10h5M9.5 12.5h3'
        fill='none'
        strokeWidth='1.5'
        strokeLinecap='round'
        className='stroke-primary'
      />
    </svg>
  );
}

